|      سندِ صادرنشده یعنی کارنامه‌ای که هیچ‌وقت نمی‌توان صادر کرد.
|   ۳. مجوز: نمره کار امور مالی و پذیرش نیست، و کارنامهٔ رسمیِ همهٔ دوره‌های
|      دانش‌آموز سندِ مدیریت است — دبیر نمرهٔ کلاس خودش را می‌بیند نه سند را.
*/

class TranscriptTest extends TestCase
{
    use RefreshDatabase;

    private function student(): Student
    {
        return Student::factory()->create();
    }

    private function actingAsRole(Role $role): User
    {
        $user = User::factory()->role($role)->create();

        $this->actingAs($user);

        return $user;
    }

    /** ثبت‌نام قطعی یک دانش‌آموز در دوره و برگرداندن همان دوره. */
    private function enrolled(Student $student, ?Course $course = null): Course
    {
        $course ??= Course::factory()->create();

        CourseEnrollment::enroll($student, $course)->confirm();

        return $course;
    }

    // ── سند ────────────────────────────────────────────────

    public function test_the_transcript_is_a_standalone_official_document(): void
    {
        $this->actingAsRole(Role::Admin);

        $student = $this->student();
        $course = $this->enrolled($student);
        Grade::record($student, $course, GradeType::Homework, 'تکلیف اول', 18, gradedAt: '2026-11-01');

        $response = $this->get(route('students.transcript', $student));

        $response->assertOk();

        // منو و سایهٔ پنل روی کاغذ نباید باشند — نیمهٔ منو سند نیست
        $response->assertDontSee('drawer');

        $response->assertSee('کارنامه رسمی')
            ->assertSee($student->full_name)
            ->assertSee('تکلیف اول')
            ->assertSee(\\App\\Models\\Setting::academyName())
            ->assertSee('امضای مدیر آموزشگاه')
            ->assertSee('امضای دانش‌آموز');

        // تاریخ صدور و تاریخ نمره شمسی‌اند
        $response
            ->assertSee(to_persian_digits(jalali_date(now())))
            ->assertSee(to_persian_digits(jalali_date('2026-11-01')));

        // R1: هیچ تاریخ میلادی نباید به چاپ برسد
        $response->assertDontSee(now()->toDateString())
            ->assertDontSee('2026-11-01');

        // شماره سند: شناسهٔ دانش‌آموز چهار رقمی در کنار سال شمسی
        $response->assertSee(
            to_persian_digits(str_pad((string) $student->id, 4, '0', STR_PAD_LEFT)),
            false
        );
    }

    public function test_a_student_without_grades_still_gets_a_document(): void
    {
        $this->actingAsRole(Role::Admin);

        $student = $this->student();
        $this->enrolled($student);

        $this->get(route('students.transcript', $student))
            ->assertOk()
            ->assertSee('کارنامه رسمی')
            ->assertSee('فاقد سابقه')
            ->assertDontSee('مردود');
    }

    public function test_a_student_with_no_enrollment_at_all_still_gets_a_document(): void
    {
        $this->actingAsRole(Role::Admin);

        $this->get(route('students.transcript', $this->student()))
            ->assertOk()
            ->assertSee('کارنامه رسمی')
            ->assertSee('فاقد سابقه');
    }

    public function test_the_transcript_states_pass_or_failure(): void
    {
        $this->actingAsRole(Role::Deputy);

        $passing = $this->student();
        $course = $this->enrolled($passing);
        Grade::record($passing, $course, GradeType::Final, 'پایان‌ترم', 15);

        $failing = $this->student();
        $other = $this->enrolled($failing);
        Grade::record($failing, $other, GradeType::Final, 'پایان‌ترم', 8);

        $this->get(route('students.transcript', $passing))
            ->assertOk()
            ->assertSee('قبولی')
            ->assertDontSee('مردود');

        $this->get(route('students.transcript', $failing))
            ->assertOk()
            ->assertSee('مردود');
    }

    public function test_the_transcript_shows_planned_and_attended_hours(): void
    {
        $this->actingAsRole(Role::Admin);

        $student = $this->student();
        // ۱۰ جلسهٔ ۹۰ دقیقه‌ای = ۱۵ ساعت برنامه
        $course = Course::factory()->create(['session_count' => 10, 'session_duration' => 90]);
        $this->enrolled($student, $course);

        // یک جلسهٔ ۹۰ دقیقه‌ای که دانش‌آموز در آن حاضر بوده
        $session = ClassSession::factory()->for($course)->create([
            'start_minute' => 8 * 60,
            'end_minute' => 8 * 60 + 90,
        ]);
        Attendance::recordFor($session, [
            ['student_id' => $student->id, 'status' => 'present'],
        ]);

        $this->get(route('students.transcript', $student))
            ->assertOk()
            ->assertSee('ساعت برنامه')
            ->assertSee('ساعت حضور')
            ->assertSee(to_persian_digits('15'))
            ->assertSee(to_persian_digits('1.5'));
    }

    // ── دسترسی ────────────────────────────────────────────

    public function test_only_management_can_open_the_transcript(): void
    {
        $student = $this->student();

        foreach ([Role::Finance, Role::Reception, Role::Teacher] as $role) {
            $this->actingAsRole($role);

            $this->get(route('students.transcript', $student))->assertForbidden();
        }
    }

    public function test_a_guest_is_sent_to_login(): void
    {
        $this->get(route('students.transcript', $this->student()))
            ->assertRedirect(route('login'));
    }

    public function test_the_student_file_offers_the_transcript_to_academic_roles(): void
    {
        $student = $this->student();
        $url = route('students.transcript', $student);

        $this->actingAsRole(Role::Admin);
        $this->get(route('students.show', $student))
            ->assertOk()
            ->assertSee($url, false);

        // امور مالی پرونده را برای بدهی باز می‌کند، نه برای نمره
        $this->actingAsRole(Role::Finance);
        $this->get(route('students.show', $student))
            ->assertOk()
            ->assertDontSee($url, false);
    }
}
