{"content":"<?php

namespace App\Services;

use App\Enums\EnrollmentStatus;
use App\Models\Attendance;
use App\Models\Course;
use App\Models\Grade;
use App\Models\Student;
use Illuminate\Support\Collection;

/**
 * ساخت دادهٔ کارنامهٔ رسمیِ یک دانش‌آموز برای چاپ.
 *
 * این کلاس فقط می‌خواند و می‌شمارد؛ قالب و امضا کار view است. جدا بودنش از
 * controller برای این است که همان محاسبه‌ها را گزارش دیگر هم بخواهد و نباید
 * دو بار نوشته شود — «نمرهٔ نهایی» باید همه‌جا یک عدد باشد.
 */
class StudentTranscript
{
    /**
     * نمرهٔ قبولی از ۲۰.
     *
     * ثابت است نه تنظیم: کارنامهٔ رسمی سندی است که بعداً با آن مقایسه می‌شود و
     * عددی که با هر بار عوض شدن تنظیمات عوض شود، سندِ قابل استناد نیست.
     */
    public const PASS_SCORE=***    public function __construct(private readonly WeightedAverage $average = new WeightedAverage) {}

    /**
     * @return array{
     *     student: Student,
     *     document_number: string,
     *     issued_on: string,
     *     rows: Collection<int, array>,
     *     has_grades: bool,
     *     final_average: float|null,
     *     status: string
     * }
     */
    public function build(Student $student): array
    {
        $rows = $this->courseRows($student);

        $finals = $rows
            ->pluck('final_score')
            ->filter(fn ($score) => $score !== null)
            ->values();

        $average = $finals->isEmpty() ? null : round($finals->avg(), 2);

        return [
            'student' => $student,
            'document_number' => $this->documentNumber($student),
            'issued_on' => jalali_date(now()),
            'rows' => $rows,
            'has_grades' => $finals->isNotEmpty(),
            'final_average' => $average,
            'status' => $this->statusFor($average),
        ];
    }

    /**
     * هر دورهٔ ثبت‌نام‌شدهٔ قطعی با ریزنمرات و جمع‌بندی‌اش.
     *
     * دوره‌های لغوشده و ردشده نمی‌آیند: یک ثبت‌نامِ ردشده در کنار دوره‌های
     * واقعی، سند را مبهم می‌کند.
     *
     * @return Collection<int, array>
     */
    public function courseRows(Student $student): Collection
    {
        return $student->enrollments()
            ->where('status', EnrollmentStatus::Confirmed->value)
            ->with('course.subject')
            ->orderBy('course_id')
            ->get()
            ->map(fn ($enrollment) => $this->row($student, $enrollment->course))
            ->values();
    }

    /** @return array */
    private function row(Student $student, Course $course): array
    {
        $grades = Grade::forStudentInCourse($student, $course)
            ->sortBy(fn (Grade $grade) => [$grade->type->value, $grade->title])
            ->values();

        $final = $grades->isEmpty() ? null : $this->average->finalScore($student, $course);

        return [
            'course' => $course,
            'grades' => $grades,
            'count' => $grades->count(),
            'sum' => round($grades->sum(fn (Grade $grade) => (float) $grade->score), 2),
            'max_sum' => round($grades->sum(fn (Grade $grade) => (float) $grade->max_score), 2),
            'average_percentage' => $grades->isEmpty()
                ? null
                : round($grades->sum(fn (Grade $grade) => $grade->percentage()) / $grades->count(), 2),
            'final_score' => $final,
            'status' => $this->statusFor($final),
            'planned_hours' => $course->totalHours(),
            'attended_hours' => $this->attendedHours($student, $course),
        ];
    }

    /**
     * ساعت حضور واقعی دانش‌آموز در دوره.
     *
     * از روی خودِ ثبت حضور حساب می‌شود، نه از برنامه: «ساعت برنامه» چیزی است
     * که آموزشگاه وعده داده، «ساعت حضور» چیزی است که اتفاق افتاده. این دو در
     * سند رسمی باید کنار هم باشند تا غیبت معلوم شود.
     */
    public function attendedHours(Student $student, Course $course): float
    {
        $rows = Attendance::query()
            ->where('student_id', $student->id)
            ->whereHas('classSession', fn ($query) => $query->where('course_id', $course->id))
            ->with('classSession')
            ->get()
            ->filter(fn (Attendance $attendance) => $attendance->attended());

        if ($rows->isEmpty()) {
            return 0.0;
        }

        return round(
            $rows->sum(fn (Attendance $attendance) => $attendance->classSession->durationMinutes()) / 60,
            2
        );
    }

    /**
     * وضعیت قبولی از روی نمره.
     *
     * نمرهٔ نداشتن «مردود» نیست: نمره‌ای ثبت نشده یعنی چیزی برای قضاوت وجود
     * ندارد، و نوشتن «مردود» دربارهٔ کسی که امتحان نداده اتهام است.
     */
    public function statusFor(?float $score): string
    {
        if ($score === null) {
            return 'فاقد سابقه';
        }

        return $score >= self::PASS_SCORE ? 'قبولی' : 'مردود';
    }

    /**
     * شمارهٔ سند: کد دانش‌آموز در کنار سال شمسیِ صدور.
     *
     * سال شمسی است نه میلادی چون این شماره در سندِ چاپی خوانده می‌شود و باید با
     * تاریخی که کنارش چاپ شده یکی باشد.
     */
    public function documentNumber(Student $student): string
    {
        return sprintf(
            'ک-%s-%s',
            jalali_date(now(), 'Y'),
            str_pad((string) $student->id, 4, '0', STR_PAD_LEFT)
        );
    }

    /** ساعت برای چاپ: ۱۵ و ۱٫۵، نه ۱۵٫۰. */
    public function hoursLabel(float $hours): string
    {
        $formatted = number_format($hours, 2, '.', '');

        if (str_contains($formatted, '.')) {
            $formatted = rtrim(rtrim($formatted, '0'), '.');
        }

        return to_persian_digits($formatted === '' ? '0' : $formatted);
    }
}
