namespace App\Http\Controllers;

use App\Models\Student;
use App\Services\StudentTranscript;
use Illuminate\Contracts\View\View;

/**
 * کارنامهٔ رسمی چاپی.
 *
 * مثل چاپ فاکتور و فیش حقوقی از layout پنل جدا است: منو و سایه روی کاغذ
 * نمی‌آیند و سندی که نیمه‌اش منو است، سند رسمی نیست.
 */
class TranscriptController extends Controller
{
    public function show(Student $student, StudentTranscript $transcript): View
    {
        return view('students.print.transcript', $transcript->build($student));
    }
}
